args.new:
def _ndtri(p):  # noqa: ANN001, ANN202
    """Inverse standard-normal CDF (statistics.NormalDist.inv_cdf).

    Vectorised so it is a drop-in replacement for scipy.special.ndtri.
    """
    arr = np.asarray(p, dtype=np.float64)
    if arr.ndim == 0:
        return _nd.inv_cdf(float(arr))
    flat = arr.ravel()
    out = np.array([_nd.inv_cdf(float(v)) for v in flat], dtype=np.float64)
    return out.reshape(arr.shape)

args.old:
